#!/usr/bin/env bash
# Generated by scripts/build-cdx.sh; edit bin/cdx.d/* and rebuild.
set -euo pipefail

# Fancy-ish log strings
CODEX_TERM_IS_DUMB=0
if [[ "${TERM:-}" == "dumb" ]]; then
  CODEX_TERM_IS_DUMB=1
fi

CODEX_COLOR_ENABLED=0
if [[ -t 1 ]] && [[ -z "${NO_COLOR:-}" ]] && (( ! CODEX_TERM_IS_DUMB )); then
  CODEX_COLOR_ENABLED=1
fi

if (( CODEX_COLOR_ENABLED )); then
  BOLD="\033[1m"
  DIM="\033[2m"
  GREEN="\033[32m"
  YELLOW="\033[33m"
  ORANGE="\033[38;5;208m"
  CYAN="\033[96m"
  BLUE="\033[36m"
  MAGENTA="\033[35m"
  RED="\033[31m"
  RESET="\033[0m"
else
  BOLD=""
  DIM=""
  GREEN=""
  YELLOW=""
  ORANGE=""
  CYAN=""
  BLUE=""
  MAGENTA=""
  RED=""
  RESET=""
fi

if (( CODEX_TERM_IS_DUMB )); then
  LOG_PREFIX_INFO="${LOG_PREFIX_INFO:->}"
else
  LOG_PREFIX_INFO="${LOG_PREFIX_INFO:-»}"
fi
LOG_PREFIX_WARN="${LOG_PREFIX_WARN:-!}"
LOG_PREFIX_ERROR="${LOG_PREFIX_ERROR:-x}"

log_info() {
  (( CODEX_SILENT )) && return
  local msg="${1-}"
  while IFS= read -r line; do
    printf "%b%s%b %s\n" "${BLUE}${BOLD}" "$LOG_PREFIX_INFO" "${RESET}" "$line"
  done <<< "$msg"
}

log_warn() {
  (( CODEX_SILENT )) && return
  local msg="${1-}"
  while IFS= read -r line; do
    printf "%b%s%b %s\n" "${YELLOW}${BOLD}" "$LOG_PREFIX_WARN" "${RESET}" "$line" >&2
  done <<< "$msg"
}

log_error() {
  local msg="${1-}"
  while IFS= read -r line; do
    printf "%b%s%b %s\n" "${RED}${BOLD}" "$LOG_PREFIX_ERROR" "${RESET}" "$line" >&2
  done <<< "$msg"
}

log_debug() {
  (( CODEX_SILENT )) && return 0
  (( CODEX_DEBUG )) && printf "%b[debug]%b %s\n" "${DIM}" "${RESET}" "$1" >&2
  return 0
}

CDX_BOOT_START_NS=""
cdx_time_ms() {
  date +%s%N 2>/dev/null || true
}

cdx_elapsed_ms() {
  local start_ns="$1"
  local end_ns
  end_ns="$(cdx_time_ms)"
  if [[ "$start_ns" =~ ^[0-9]+$ ]] && [[ "$end_ns" =~ ^[0-9]+$ ]]; then
    printf '%s' $(( (end_ns - start_ns) / 1000000 ))
  fi
}

cdx_debug_phase() {
  local label="$1"
  local start_ns="$2"
  local elapsed
  elapsed="$(cdx_elapsed_ms "$start_ns")"
  if [[ -n "$elapsed" ]]; then
    log_debug "timing: ${label} ${elapsed}ms"
  fi
}

CDX_BOOT_START_NS="$(cdx_time_ms)"

lowercase() {
  local input="${1-}"
  printf '%s' "$input" | tr '[:upper:]' '[:lower:]'
}

SED_ERE_FLAG=""
detect_sed_ere_flag() {
  if [[ -n "$SED_ERE_FLAG" ]]; then
    return 0
  fi
  if echo x | sed -r 's/x/x/' >/dev/null 2>&1; then
    SED_ERE_FLAG="-r"
  else
    SED_ERE_FLAG="-E"
  fi
}

strip_ansi_sgr() {
  local text="${1-}"
  detect_sed_ere_flag
  sed "$SED_ERE_FLAG" 's/\x1B\[[0-9;]*[mK]//g' <<<"$text"
}

sha256_file() {
  local target="${1-}"
  [[ -n "$target" ]] || return 1
  [[ -f "$target" ]] || return 1

  if command -v sha256sum >/dev/null 2>&1; then
    sha256sum "$target" | awk '{print $1}'
    return 0
  fi
  if command -v shasum >/dev/null 2>&1; then
    shasum -a 256 "$target" | awk '{print $1}'
    return 0
  fi
  if command -v openssl >/dev/null 2>&1; then
    openssl dgst -sha256 "$target" | awk '{print $NF}'
    return 0
  fi
  if command -v python3 >/dev/null 2>&1; then
    python3 - "$target" <<'PY'
import hashlib, pathlib, sys
print(hashlib.sha256(pathlib.Path(sys.argv[1]).read_bytes()).hexdigest())
PY
    return 0
  fi

  return 1
}

